-- ============================================================
-- Alagoas Motos — Painel de Valores e Mercadorias
-- Execute este arquivo INTEIRO no Supabase SQL Editor.
-- Ele cria as tabelas, libera acesso, habilita Realtime e
-- importa todos os dados de revisoes.json.
-- Pode ser executado novamente (recria os dados do zero).
-- ============================================================

DROP TABLE IF EXISTS rev_servico_itens CASCADE;
DROP TABLE IF EXISTS rev_servicos_avulsos CASCADE;
DROP TABLE IF EXISTS rev_revisao_itens CASCADE;
DROP TABLE IF EXISTS rev_revisoes CASCADE;
DROP TABLE IF EXISTS rev_modelos CASCADE;
DROP TABLE IF EXISTS rev_mercadorias CASCADE;
DROP TABLE IF EXISTS rev_mao_de_obra CASCADE;

CREATE TABLE rev_modelos (
  id        BIGSERIAL PRIMARY KEY,
  nome      TEXT NOT NULL UNIQUE,
  periodo   TEXT,
  ordem     INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE rev_revisoes (
  id                 BIGSERIAL PRIMARY KEY,
  modelo_id          BIGINT NOT NULL REFERENCES rev_modelos(id) ON DELETE CASCADE,
  numero             INTEGER NOT NULL,
  km                 INTEGER,
  meses              INTEGER,
  tmo_horas          NUMERIC,
  mao_de_obra_gratis BOOLEAN NOT NULL DEFAULT false,
  mao_de_obra_valor  NUMERIC,
  servicos           JSONB NOT NULL DEFAULT '[]'::jsonb,
  UNIQUE (modelo_id, numero)
);

-- Catalogo geral de mercadorias (reaproveitado entre revisoes)
CREATE TABLE rev_mercadorias (
  id             BIGSERIAL PRIMARY KEY,
  codigo         TEXT NOT NULL UNIQUE,
  descricao      TEXT NOT NULL,
  valor_unitario NUMERIC
);

CREATE TABLE rev_revisao_itens (
  id             BIGSERIAL PRIMARY KEY,
  revisao_id     BIGINT NOT NULL REFERENCES rev_revisoes(id) ON DELETE CASCADE,
  mercadoria_id  BIGINT NOT NULL REFERENCES rev_mercadorias(id) ON DELETE CASCADE,
  quantidade     NUMERIC NOT NULL DEFAULT 1,
  valor_unitario NUMERIC,   -- NULL = usa o valor do catalogo
  descricao      TEXT       -- NULL = usa a descricao do catalogo
);

CREATE TABLE rev_servicos_avulsos (
  id                BIGSERIAL PRIMARY KEY,
  nome              TEXT NOT NULL,
  mao_de_obra_valor NUMERIC,
  ordem             INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE rev_servico_itens (
  id             BIGSERIAL PRIMARY KEY,
  servico_id     BIGINT NOT NULL REFERENCES rev_servicos_avulsos(id) ON DELETE CASCADE,
  mercadoria_id  BIGINT NOT NULL REFERENCES rev_mercadorias(id) ON DELETE CASCADE,
  quantidade     NUMERIC NOT NULL DEFAULT 1,
  valor_unitario NUMERIC,
  descricao      TEXT
);

CREATE TABLE rev_mao_de_obra (
  id                  BIGSERIAL PRIMARY KEY,
  modelos             TEXT NOT NULL,
  tmo_hora_valor      NUMERIC,
  revisao_geral_valor NUMERIC,
  ordem               INTEGER NOT NULL DEFAULT 0
);

CREATE INDEX idx_rev_revisoes_modelo ON rev_revisoes(modelo_id);
CREATE INDEX idx_rev_itens_revisao ON rev_revisao_itens(revisao_id);
CREATE INDEX idx_rev_servico_itens ON rev_servico_itens(servico_id);

-- Acesso (o app usa a anon key; o painel admin e protegido por login no proprio app)
ALTER TABLE rev_modelos          ENABLE ROW LEVEL SECURITY;
ALTER TABLE rev_revisoes         ENABLE ROW LEVEL SECURITY;
ALTER TABLE rev_mercadorias      ENABLE ROW LEVEL SECURITY;
ALTER TABLE rev_revisao_itens    ENABLE ROW LEVEL SECURITY;
ALTER TABLE rev_servicos_avulsos ENABLE ROW LEVEL SECURITY;
ALTER TABLE rev_servico_itens    ENABLE ROW LEVEL SECURITY;
ALTER TABLE rev_mao_de_obra      ENABLE ROW LEVEL SECURITY;

DO $$
DECLARE t TEXT;
BEGIN
  FOREACH t IN ARRAY ARRAY['rev_modelos','rev_revisoes','rev_mercadorias','rev_revisao_itens','rev_servicos_avulsos','rev_servico_itens','rev_mao_de_obra'] LOOP
    EXECUTE format('GRANT SELECT, INSERT, UPDATE, DELETE ON public.%I TO anon, authenticated', t);
    EXECUTE format('GRANT ALL ON public.%I TO service_role', t);
    EXECUTE format('GRANT USAGE, SELECT ON SEQUENCE public.%I_id_seq TO anon, authenticated, service_role', t);
    EXECUTE format('CREATE POLICY %I ON public.%I FOR ALL USING (true) WITH CHECK (true)', t || '_full_access', t);
    EXECUTE format('ALTER PUBLICATION supabase_realtime ADD TABLE public.%I', t);
    EXECUTE format('ALTER TABLE public.%I REPLICA IDENTITY FULL', t);
  END LOOP;
END $$;

